+    private ShardRouting getShard(ShardId shardId, boolean isPrimary, ShardRoutingState state, ShardRouting.Role role) {
+        return new ShardRouting(
+            shardId,
+            state == ShardRoutingState.UNASSIGNED ? null : randomIdentifier(),
